    def parse_balance(self, balances) -> Balances:
        timestamp = self.parse_date(self.safe_string(self.last_response_headers, 'Date'))
        result = {
            'timestamp': timestamp,
            'datetime': self.iso8601(timestamp),
            'info': balances,
        }
        for i in range(0, len(balances)):
            balance = balances[i]
            code = self.safe_currency_code(self.safe_string(balance, 'currency'))
            lendBorrow = Precise.string_add(
                self.safe_string(balance, 'lendReserved'),
                self.safe_string(balance, 'borrowReserved')
            )
            used = Precise.string_add(
                lendBorrow,
                self.safe_string(balance, 'reserved')
            )
            debt = Precise.string_sub(
                self.safe_string(balance, 'borrowedAmount'),
                self.safe_string(balance, 'borrowReserved')
            )
            result[code] = {
                'free': self.safe_float(balance, 'available'),
                'used': used,
                'total': self.safe_float(balance, 'total'),
                'debt': debt,
            }
        return self.safe_balance(result)

