    def parse_order(self, order, market: Market = None) -> Order:
        orderStatus = self.safe_string_2(order, 'status', 'orderStatusType')
        status = None
        if self.in_array(orderStatus, ['Placed', 'Active', 'Order Modified', 'Partially Filled']):
            status = 'open'
        elif self.in_array(orderStatus, ['Failed', 'Cancelled']):
            failedReason = self.safe_string(order, 'failedReason')
            if self.in_array(failedReason, ['Insufficient Balance', 'The borrow amount is unavailable currently, please try again later']):
                status = 'rejected'
            else:
                status = 'canceled'
        elif orderStatus == 'Filled':
            status = 'closed'
        orderType = self.safe_string_2(order, 'type', 'orderType')
        typeParse = None
        postOnly = None
        if orderType is not None:
            if orderType == 'market':
                typeParse = 'market'
                postOnly = False
            elif orderType.find('limit') >= 0:
                typeParse = 'limit'
                postOnly = (orderType.find('post-only') >= 0)
        totalFee = self.safe_number_2(order, 'totalFee', 'executedFee')
        feeCurrency = self.safe_string(order, 'feeCurrency')
        fee = None
        if totalFee is not None:
            fee = {
                'cost': totalFee,
                'currency': self.safe_currency_code(feeCurrency),
                'rate': None,
            }
        executedPrice = self.safe_number(order, 'executedPrice')
        orderPrice = self.safe_number_2(order, 'price', 'originalPrice')
        finalPrice = None
        if (executedPrice is not None) and (executedPrice != 0):
            finalPrice = executedPrice
        else:
            finalPrice = orderPrice
        datetime = self.safe_string_2(order, 'createdAt', 'orderCreatedAt')
        updateDatetime = self.safe_string_2(order, 'updatedAt', 'orderUpdatedAt')
        result = {
            'id': self.safe_string(order, 'orderId'),
            'clientOrderId': self.safe_string(order, 'customerOrderId'),
            'timestamp': self.parse8601(datetime),
            'datetime': datetime,
            'symbol': self.safe_symbol(self.safe_string(order, 'currencyPair')),
            'type': typeParse,
            'side': self.safe_string_2(order, 'side', 'orderSide'),
            'lastTradeTimestamp': None,
            'lastUpdateTimestamp': self.parse8601(updateDatetime),
            'price': finalPrice,
            'amount': self.safe_string_2(order, 'executedQuantity', 'originalQuantity'),
            'cost': self.safe_string(order, 'total'),
            'average': self.safe_string(order, 'averagePrice'),
            'filled': self.safe_string(order, 'totalExecutedQuantity'),
            'remaining': self.safe_string(order, 'remainingQuantity'),
            'timeInForce': self.safe_string(order, 'timeInForce'),
            'postOnly': postOnly,
            'trades': None,
            'reduceOnly': self.safe_value(order, 'reduceOnly'),
            'triggerPrice': None,
            'takeProfitPrice': None,
            'stopLossPrice': None,
            'status': status,
            'fee': fee,
            'info': order,
        }
        return self.safe_order(result, market)

    def create_order(self, symbol: str, type: OrderType, side: OrderSide, amount: float, price: Num = None, params={}) -> Order:
        """
        https://docs.valr.com/#5beb7328-24ca-4d8a-84f2-6029725ad923
        Create a trade order
        :param str symbol: unified symbol of the market to create an order in
        :param str type: 'market' or 'limit'
        :param str side: 'buy' or 'sell'
        :param float amount: how much of currency you want to trade in units of base currency
        :param float [price]: the price at which the order is to be fullfilled, in units of the quote currency. If included in market order, use quote amount
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :param dict [params.postOnly]: if True will place a limit order and fail if matched immidiately
        :param dict [params.clientOrderId]: an optional field which can be specified by clients to track self order using their own internal order management systems
        :param dict [params.allowMargin]: Set to True for a margin / leverage trade
        :returns dict: an `order structure <https://docs.ccxt.com/#/?id=order-structure>` with only the id and symbol added
        """
        self.load_markets()
        response = None
        self.check_required_symbol_argument('createOrder', symbol)
        marketId = self.market_id(symbol)
        if side != 'buy' and side != 'sell':
            raise InvalidOrder(self.id + ' createOrder() - "side" must be either "buy" or "sell".')
        body = {
            'side': side.upper(),
            'pair': marketId,
        }
        # Optional parameters
        if self.safe_string(params, 'clientOrderId'):
            body['customerOrderId'] = self.safe_string(params, 'clientOrderId')
        if self.safe_string(params, 'allowMargin'):
            body['allowMargin'] = self.safe_string(params, 'allowMargin')
        self.omit(params, ['allowMargin', 'clientOrderId'])
        if type == 'market':
            if price:
                body['quoteAmount'] = amount
            else:
                body['baseAmount'] = amount
            self.omit(params, ['baseAmount', 'quoteAmount'])
            response = self.privatePostOrdersMarket(self.extend(body, params))
        elif type == 'limit':
            body['price'] = self.number_to_string(price)
            body['quantity'] = self.number_to_string(amount)
            if self.safe_string(params, 'postOnly'):
                body['postOnly'] = self.safe_bool(params, 'postOnly')
                self.omit(params, 'postOnly')
            response = self.privatePostOrdersLimit(self.extend(body, params))
        else:
            raise InvalidOrder(self.id + ' createOrder() - "type" must be either "market" or "limit" to create an order.')
        timestamp = self.parse_date(self.safe_string(self.last_response_headers, 'Date'))
        return self.parse_order({
            'createdAt': self.iso8601(timestamp),
            'orderId': self.safe_string(response, 'id'),
            'currencyPair': marketId,
            'customerOrderId': self.safe_string(params, 'clientOrderId'),
        })

