    def edit_order(self, id: str, symbol: str, type: OrderType, side: OrderSide, amount: Num = None, price: Num = None, params={}) -> Order:
        """
        https://docs.valr.com/#0d31c914-0393-463b-966a-97dbc50554fd
        Edit a trade order
        :param str id: order id
        :param str symbol: unified symbol of the market to create an order in
        :param str type: 'market' or 'limit'
        :param str side: 'buy' or 'sell'
        :param float [amount]: how much of currency you want to trade in units of base currency
        :param float [price]: the price at which the order is to be fullfilled, in units of the quote currency. If included in market order, use quote amount
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :param str [params.matchRetain]: RETAIN_ORIGINAL(default) keeps original order, CANCEL_ORIGINAL to cancle original order or REPRICE to reprice within one tick
        :param boolean [params.setTotal]: If True(default), new amount will takes current fill quantity into account, otherwise it simply forces new amount to be set.
        :param dict [params.clientOrderId]: an optional field which can be specified by clients to track self order using their own internal order management systems
        :returns dict: an `order structure <https://docs.ccxt.com/#/?id=order-structure>` with only the id and symbol added
        """
        self.load_markets()
        marketId = self.market_id(symbol)
        modifyMethod = self.safe_string(params, 'matchRetain', 'RETAIN_ORIGINAL')
        orderFormat = {
            'orderId': id,
            'pair': marketId,
            'modifyMatchStrategy': modifyMethod,
        }
        if price is not None:
            orderFormat['newPrice'] = self.number_to_string(price)
        if amount is not None:
            amountStrategy = self.safe_bool(params, 'setTotal', True)
            amountMethod = 'newTotalQuantity' if (amountStrategy) else 'newRemainingQuantity'
            orderFormat[amountMethod] = self.number_to_string(amount)
        if self.safe_string(params, 'clientOrderId'):
            orderFormat['customerOrderId'] = self.safe_string(params, 'clientOrderId')
        params = self.omit(params, ['matchRetain', 'setTotal', 'clientOrderId'])
        response = self.privatePutOrdersModify(self.extend(orderFormat, params))
        return self.parse_order({
            'orderUpdatedAt': self.iso8601(self.parse_date(self.safe_string(self.last_response_headers, 'Date'))),
            'orderId': id,
            'transactionId': self.safe_string(response, 'id'),
            'currencyPair': marketId,
            'customerOrderId': self.safe_string(params, 'clientOrderId'),
        })

    def cancel_order(self, id: str, symbol: Str = None, params={}) -> Order:
        """
        https://docs.valr.com/#3d9ba169-7222-4c0f-ab08-87c22162c0c4
        cancels an open order
        :param str id: order id or customer order id
        :param str symbol: unified symbol of the market the order was made in
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :param boolean [params.clientOrderId]: ID is for clientOrderId field and associate API call(default is False)
        :returns dict: an `order structure <https://docs.ccxt.com/#/?id=order-structure>` with only the id and symbol added
        """
        self.load_markets()
        self.check_required_symbol_argument('cancelOrder', symbol)
        useClientOrderId = self.safe_bool(params, 'clientOrderId', False)
        marketId = self.market_id(symbol)
        orderFormat = {'pair': marketId}
        if useClientOrderId:
            params = self.omit(params, 'clientOrderId')
            orderFormat['customerOrderId'] = id
        else:
            orderFormat['orderId'] = id
        self.privateDeleteOrdersOrder(self.extend(orderFormat, params))
        return self.parse_order({
            'orderUpdatedAt': self.iso8601(self.parse_date(self.safe_string(self.last_response_headers, 'Date'))),
            'orderId': id if (not useClientOrderId) else None,
            'customerOrderId': id if (useClientOrderId) else None,
            'currencyPair': marketId,
        })

    def cancel_all_orders(self, symbol: Str = None, params={}) -> List[Order]:
        """
        https://docs.valr.com/#90822956-7e25-48a8-bd14-a83fb8766b46
        cancels all an open order or all open orders on a specific market
        :param str [symbol]: unified symbol of the market the order was made in
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :returns dict: an list of `order structure <https://docs.ccxt.com/#/?id=order-structure>` with only the id and option symbol added
        """
        self.load_markets()
        response = None
        marketId = None
        if symbol is None:
            response = self.privateDeleteOrders(params)
        else:
            self.check_required_symbol_argument('cancelAllOrders', symbol)
            marketId = self.market_id(symbol)
            body = {
                'pair': marketId,
            }
            response = self.privateDeleteOrdersPair(self.extend(body, params))
        timestamp = self.parse_date(self.safe_string(self.last_response_headers, 'Date'))
        for i in range(0, len(response)):
            response[i]['currencyPair'] = marketId
            response[i]['orderUpdatedAt'] = self.iso8601(timestamp)
        return self.parse_orders(response)

