    def parse_trade(self, trade: object, market: Market = None) -> Trade:
        symbol = self.safe_symbol(self.safe_string(trade, 'currencyPair'))
        timestamp = self.parse8601(self.safe_string(trade, 'tradedAt'))
        feeCost = self.safe_number(trade, 'totalFee')
        fee = {
            'currency': self.safe_currency_code(self.safe_string(trade, 'feeCurrency')),
            'cost': feeCost,
            'rate': None,
        }
        return self.safe_trade({
            'info': trade,
            'amount': self.safe_number(trade, 'quantity'),
            'clientOrderId': self.safe_string(trade, 'customerOrderId'),
            'cost': self.safe_number(trade, 'quoteVolume'),
            'datetime': self.safe_string(trade, 'tradedAt'),
            'fee': fee,
            'id': self.safe_string(trade, 'id'),
            'order': self.safe_string(trade, 'orderId'),
            'price': self.safe_number(trade, 'price'),
            'side': self.safe_string_2(trade, 'side', 'takerSide'),
            'symbol': symbol,
            'takerOrMaker': None,
            'timestamp': timestamp,
        })

    def fetch_ohlcv(self, symbol: str, timeframe: str = '1m', since: Int = None, limit: Int = None, params={}) -> List[list]:
        self.load_markets()
        market = self.market(symbol)
        if limit is None:
            limit = 100  # default 100, max 300
        request = {
            'pair': market['id'],
            'periodSeconds': self.parse_timeframe(timeframe),
            'limit': limit,
            'includeEmpty': True,
            # 'startTime': self.parse_to_int(since / 1000)  # convert milliseconds to seconds
        }
        response = self.publicGetPairBuckets(self.extend(request, params))
        # [
        #     {
        #         currencyPairSymbol: "USDTZAR",
        #         bucketPeriodInSeconds: "300",
        #         startTime: "2026-03-11T19:20:00Z",
        #         open: "16.5849",
        #         high: "16.5849",
        #         low: "16.5849",
        #         close: "16.5849",
        #         volume: "0",
        #         quoteVolume: "0",
        #     },
        #     {
        #         currencyPairSymbol: "USDTZAR",
        #         bucketPeriodInSeconds: "300",
        #         startTime: "2026-03-11T19:15:00Z",
        #         open: "16.5827",
        #         high: "16.5849",
        #         low: "16.5827",
        #         close: "16.5849",
        #         volume: "3173.0137",
        #         quoteVolume: "52618.28619867",
        #     }, ...
        # ]
        parsed = self.parse_ohlcvs(response, market, timeframe, None, limit)
