    def fetch_ledger(self, code: Str = None, since: Int = None, limit: Int = None, params={}):
        """
        https://docs.valr.com/#0d7cc0ff-b8ca-4e1f-980e-36d07672e53d
        fetch the history of changes, actions done by the user or operations that altered balance of the user
        :param str [code]: uunified currency code, default is None
        :param int [since]: timestamp in ms of the earliest ledger entry, default is None
        :param int [limit]: max number of ledger entrys to return, default is None
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :param dict [params.skip]: number of items to skip from list
        :param dict [params.transactionTypes]: string list of transaction types to match(see VALR docs for details)
        :returns dict: a list of `ledger entry structure <https://github.com/ccxt/ccxt/wiki/Manual#ledger-entry-structure>`
        """
        self.load_markets()
        currency = None
        queryParams = {}
        if code is not None:
            currency = self.currency(code)
            queryParams['currency'] = currency['id']
        if since is not None:
            queryParams['startTime'] = self.iso8601(since)
        if limit is not None:
            queryParams['limit'] = limit
        response = self.privateGetAccountTransactionhistory(self.extend(queryParams, params))
        params = self.omit(params, 'transactionTypes')
        accountId = {
            'account': self.safe_string(self.last_request_headers, 'X-VALR-SUB-ACCOUNT-ID', '0'),
        }
        return self.parse_ledger(response, currency, since, limit, self.extend(accountId, params))

    def parse_ledger_entry(self, item, currency: Currency = None) -> LedgerEntry:
        ledgerTypeInfo = self.safe_dict(item, 'transactionType')
        ledgerType = self.safe_string(ledgerTypeInfo, 'type')
        transactionTypes = {
            'ACCOUNT_FUNDING': ['deposit', 'in'],
            'LIMIT_BUY': ['trade', 'in'],
            'LIMIT_SELL': ['trade', 'out'],
            'MARKET_BUY': ['trade', 'in'],
            'MARKET_SELL': ['trade', 'out'],
            'SIMPLE_BUY': ['trade', 'in'],
            'SIMPLE_SELL': ['trade', 'out'],
            'AUTO_BUY': ['trade', 'in'],
            'MAKER_REWARD': ['cashback', 'in'],
            'BLOCKCHAIN_RECEIVE': ['deposit', 'in'],
            'BLOCKCHAIN_SEND': ['withdrawal', 'out'],
            'FIAT_DEPOSIT': ['deposit', 'in'],
            'FIAT_WITHDRAWAL': ['withdrawal', 'out'],
            'REFERRAL_REBATE': ['rebate', 'in'],
            'REFERRAL_REWARD': ['referral', 'in'],
            'PROMOTIONAL_REBATE': ['rebate', 'in'],
            'INTERNAL_TRANSFER': ['transfer', None],
            'FIAT_WITHDRAWAL_REVERSAL': ['deposit', 'in'],
            'PAYMENT_SENT': ['withdrawal', 'out'],
            'PAYMENT_RECEIVED': ['deposit', 'in'],
            'PAYMENT_REVERSED': ['deposit', 'in'],
            'PAYMENT_REWARD': ['cashback', 'in'],
            'OFF_CHAIN_BLOCKCHAIN_WITHDRAW': ['withdrawal', 'out'],
            'OFF_CHAIN_BLOCKCHAIN_DEPOSIT': ['deposit', 'in'],
            'SIMPLE_SWAP_BUY': ['trade', 'in'],
            'SIMPLE_SWAP_SELL': ['trade', 'out'],
            'SIMPLE_SWAP_FAILURE_REVERSAL': ['transaction', None],
            'SPOT_LEND_INTEREST_PAYMENT': ['interest', 'in'],
            'SPOT_BORROW_INTEREST_CHARGE': ['interest', 'out'],
            'FUTURES_FUNDING_PAID': ['interest', 'out'],
            'FUTURES_PNL_LOSS': ['trade', 'out'],
            'FUTURES_PNL_PROFIT': ['trade', 'in'],
        }
        # transactionDisciption = self.safe_string(transactionTypeInfo, 'Deposit')
        entryTime = self.parse_date(self.safe_string(item, 'eventAt'))
        additionalInfo = self.safe_dict(item, 'additionalInfo')
        matchEventType = self.safe_list(transactionTypes, ledgerType)
        parseType = None
        direction = None
        if matchEventType is not None:
            parseType = matchEventType[0]
            direction = matchEventType[1]
        else:
            self.log(ledgerType)
        if ledgerType == 'INTERNAL_TRANSFER':
            direction = 'in' if ('creditCurrency' in item) else 'out'
        amount = None
        code = None
        if direction == 'in':
            amount = self.safe_number(item, 'creditValue')
            code = self.safe_currency_code(self.safe_string(item, 'creditCurrency'))
        elif direction == 'out':
            amount = self.safe_number(item, 'debitValue')
            code = self.safe_currency_code(self.safe_string(item, 'debitCurrency'))
        return {
            'id': self.safe_string(item, 'id'),
            'timestamp': entryTime,
            'datetime': self.iso8601(entryTime),
            'direction': direction,
            'account': None,
            'referenceId': self.safe_string_2(additionalInfo, 'sourceTransactionId', 'orderId'),
            'referenceAccount': None,
            'type': parseType,
            'currency': code,
            'amount': amount,
            'before': 0,
            'after': 0,
            'status': 'ok',
            'fee': {
                'currency': self.safe_currency_code(self.safe_string(item, 'feeCurrency')),
                'cost': self.safe_number(item, 'feeValue'),
                'rate': None,
            },
            'info': item,
        }

    def withdraw(self, code: str, amount: float, address: str, tag: Str = None, params={}) -> Transaction:
        """
        https://docs.valr.com/#bb0ad4dc-a28d-41a3-8e59-5070bc589c5a
        https://docs.valr.com/#fb4db187-530b-4632-b933-7bdfd192bcf5
        make a withdrawal
        :param str code: unified currency code
        :param float amount: the amount to withdraw
        :param str address: the address to withdraw to
        :param str tag:
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :returns dict: a `transaction structure <https://docs.ccxt.com/#/?id=transaction-structure>`
        """
        self.load_markets()
        self.check_required_currency_code_argument('fetchWithdrawals', code)
        currency = self.safe_currency(code)
        # todo: Include 'networkType' from default currency if none provided via params
        response = None
        if self.is_fiat(code):
            withdrawalBody = {
                'currency': currency['id'],
                'linkedBankAccountId': address,
                'amount': self.number_to_string(amount),
            }
            response = self.privatePostWalletFiatCurrencyWithdraw(self.extend(withdrawalBody, params))
        else:
            withdrawalBody = {
                'currency': currency['id'],
                'address': address,
                'amount': self.number_to_string(amount),
            }
            response = self.privatePostWalletCryptoCurrencyWithdraw(self.extend(withdrawalBody, params))
        return self.parse_transaction(response)

    def parse_transaction(self, transaction, currency: Currency = None) -> Transaction:
        if 'transactionType' in transaction:
            return self.parse_transaction_history(transaction)
        timestamp = self.parse8601(self.safe_string(transaction, 'createdAt'))
        code = self.safe_currency_code(self.safe_string(transaction, 'currencyCode'))
        status = None
        if self.safe_bool(transaction, 'confirmed'):
            status = 'ok'
        transactionType = None
        if 'receiveAddress' in transaction:
            transactionType = 'deposit'
        return {
            'info': transaction,
            'id': self.safe_string(transaction, 'id'),
            'txid': self.safe_string(transaction, 'transactionHash'),
            'timestamp': timestamp,
            'datetime': self.iso8601(timestamp),
            'address': self.safe_string(transaction, 'receiveAddress'),
            'addressFrom': None,
            'addressTo': None,
            'tag': None,
            'tagFrom': None,
            'tagTo': None,
            'type': transactionType,
            'amount': self.safe_number(transaction, 'amount'),
            'currency': code,
            'status': status,
            'updated': self.parse8601(self.safe_string(transaction, 'confirmedAt')),
            'fee': None,
            'network': self.safe_string(transaction, 'networkType'),
            'comment': None,
            'internal': None,
        }

    def parse_transaction_history(self, transaction):
        transactionTypeInfo = self.safe_dict(transaction, 'transactionType')
        transactionType = self.safe_string(transactionTypeInfo, 'type')
        # transactionDisciption = self.safe_string(transactionTypeInfo, 'Deposit')
        parseType = None
        amount = None
        status = None
        currency = None
        address = None
        addressTo = None
        fee = None
        eventTime = self.parse_date(self.safe_string(transaction, 'eventAt'))
        if transactionType == 'FIAT_DEPOSIT' or transactionType == 'FIAT_WITHDRAWAL':
            parseType = 'deposit' if (transactionType == 'FIAT_DEPOSIT') else 'withdrawal'
            amount = self.safe_number_2(transaction, 'creditValue', 'debitValue')
            status = 'ok'
            currency = self.safe_currency_code(self.safe_string_2(transaction, 'creditCurrency', 'debitCurrency'))
            fee = {
                'currency': self.safe_currency_code(self.safe_string(transaction, 'feeCurrency')),
                'cost': self.safe_number(transaction, 'feeValue'),
                'rate': None,
            }
            if parseType == 'withdrawal':
                additionalInfo = self.safe_dict(transaction, 'additionalInfo')
                address = self.safe_string(additionalInfo, 'accountNumber')
                addressTo = self.safe_string(additionalInfo, 'bankName')
        return {
            'info': transaction,
            'id': self.safe_string(transaction, 'id'),
            'txid': None,
            'timestamp': eventTime,
            'datetime': self.iso8601(eventTime),
            'address': address,
            'addressFrom': None,
            'addressTo': addressTo,
            'tag': None,
            'tagFrom': None,
            'tagTo': None,
            'type': parseType,
            'amount': amount,
            'currency': currency,
            'status': status,
            'updated': None,
            'fee': fee,
            'network': None,
            'comment': None,
            'internal': None,
        }

    def fetch_cross_borrow_rates(self, params={}) -> CrossBorrowRates:
        self.load_markets()
        response = self.privateGetLoansRates(params)
        results = {}
        for i in range(0, len(response)):
            borrowRate = response[i]
            code = self.safe_currency_code(self.safe_string(borrowRate, 'currency'))
            if code is not None:
                results[code] = self.parse_borrow_rate(borrowRate)
        return results

    def parse_borrow_rate(self, info, currency: Currency = None) -> dict:
        code = self.safe_currency_code(self.safe_string(info, 'currency'))
        httpTime = self.safe_string(self.last_response_headers, 'Date')
        timestamp = self.parse_date(httpTime)
        return {
            'currency': code,
            'rate': self.safe_float(info, 'estimatedNextBorrowRate'),
            'period': 3600000,
            'timestamp': timestamp,
            'datetime': self.iso8601(timestamp),
            'info': info,
        }

