    def transfer(self, code: str, amount: float, fromAccount: str, toAccount: str, params={}) -> TransferEntry:
        self.load_markets()
        self.load_accounts()
        currency = self.safe_currency(code)
        accountsByName = self.index_by(self.accounts, 'name')
        fromAccountId = self.safe_dict(accountsByName, fromAccount)
        toAccountId = self.safe_dict(accountsByName, toAccount)
        query = {
            'fromId': fromAccountId['id'] if fromAccountId else fromAccount,
            'toId': toAccountId['id'] if toAccountId else toAccount,
            'currencyCode': currency['id'],
            'amount': amount,
            'subAccountId': '0',
        }
        self.privatePostAccountSubaccountsTransfer((self.extend(query, params)))
        responseTimestamp = self.parse_date(self.safe_string(self.last_response_headers, 'Date'))
        last_json_request = self.parse_json(self.last_request_body)
        requestedCurrency = self.safe_string(last_json_request, 'currencyCode')
        return {
            'info': None,
            'id': None,
            'timestamp': responseTimestamp,
            'datetime': self.iso8601(responseTimestamp),
            'currency': self.safe_currency_code(requestedCurrency),
            'amount': self.safe_number(last_json_request, 'amount'),
            'fromAccount': self.safe_string(last_json_request, 'fromId'),
            'toAccount': self.safe_string(last_json_request, 'toId'),
            'status': None,
        }

    def fetch_transfers(self, code: Str = None, since: Int = None, limit: Int = None, params={}) -> List[TransferEntry]:
        """
        fetches a transfer
        :param str id: transfer id
        :param int [since]: timestamp in ms of the earliest transfer to fetch
        :param int [limit]: the maximum amount of transfers to fetch
        :param dict params: extra parameters specific to the exchange api endpoint
        :returns dict: a `transfer structure <https://docs.ccxt.com/#/?id=transfer-structure>`
        """
        self.load_markets()
        self.load_accounts()
        query = {
            'transactionTypes': 'INTERNAL_TRANSFER',
        }
        currency = self.safe_currency(code)
        if code is not None:
            query['currency'] = currency['id']
        if since is not None:
            query['startTime'] = self.iso8601(since)
        if limit is not None:
            query['limit'] = limit
        response = self.privateGetAccountTransactionhistory(self.extend(query, params))
        return self.parse_transfers(response, currency, since, limit, params)

    def parse_transfer(self, transfer: dict, currency: Currency = None) -> TransferEntry:
        # [{'transactionType': {'type': 'INTERNAL_TRANSFER', 'description': 'Transfer'},
        #     'debitCurrency': 'ZAR',
        #     'debitValue': '1',
        #     'eventAt': '2024-06-13T20:49:36.846Z',
        #     'additionalInfo': {'reason': 'SUB_ACCOUNT',
        #      'reasonDescription': 'Transfer between subaccounts',
        #      'additional': 'Transfer from Primary to Development'},
        #     'id': '723a6e23-29c6-11ef-9e76-33277cfdd873'},
        #    {'transactionType': {'type': 'INTERNAL_TRANSFER', 'description': 'Transfer'},
        #     'creditCurrency': 'ZAR',
        #     'creditValue': '62629.65',
        #     'eventAt': '2024-06-12T05:19:28.689Z',
        #     'additionalInfo': {'reason': 'SUB_ACCOUNT',
        #      'reasonDescription': 'Transfer between subaccounts',
        #      'additional': 'Transfer from Trading to Primary'},]
        ledgerTypeInfo = self.safe_dict(transfer, 'transactionType')
        ledgerType = self.safe_string(ledgerTypeInfo, 'type')
        transactionTypes = {
            'INTERNAL_TRANSFER': ['transfer', None],
            # 'PAYMENT_SENT': ['withdrawal', 'out'],
            # 'PAYMENT_RECEIVED': ['deposit', 'in'],
            # 'PAYMENT_REVERSED': ['deposit', 'in'],
            # 'PAYMENT_REWARD': ['cashback', 'in'],
        }
        # transactionDisciption = self.safe_string(transactionTypeInfo, 'Deposit')
        entryTime = self.parse_date(self.safe_string(transfer, 'eventAt'))
        additionalInfo = self.safe_dict(transfer, 'additionalInfo')
        matchEventType = self.safe_list(transactionTypes, ledgerType)
        # parseType = None
        direction = None
        if matchEventType is not None:
            # parseType = matchEventType[0]
            direction = matchEventType[1]
        if ledgerType == 'INTERNAL_TRANSFER':
            direction = 'in' if ('creditCurrency' in transfer) else 'out'
        amount = None
        code = None
        if direction == 'in':
            amount = self.safe_number(transfer, 'creditValue')
            code = self.safe_currency_code(self.safe_string(transfer, 'creditCurrency'))
        elif direction == 'out':
            amount = self.safe_number(transfer, 'debitValue')
            code = self.safe_currency_code(self.safe_string(transfer, 'debitCurrency'))
        accounts = self.safe_string(additionalInfo, 'additional')
        fromIndex = accounts.find('from')
        toIndex = accounts.find('to')
        fromAccount = accounts[fromIndex + 5:toIndex - 1]
        toAccount = accounts[toIndex + 3:]
        accountsByName = self.index_by(self.accounts, 'name')
        fromAccountId = self.safe_dict(accountsByName, fromAccount)
        toAccountId = self.safe_dict(accountsByName, toAccount)
        return {
            'id': self.safe_string(transfer, 'id'),
            'timestamp': entryTime,
            'datetime': self.iso8601(entryTime),
            'currency': code,
            'amount': amount,
            'fromAccount': fromAccountId['id'] if fromAccountId else fromAccount,
            'toAccount': toAccountId['id'] if toAccountId else toAccount,
            'status': 'ok',
            'info': transfer,
        }

