    def sign(self, path, api='public', method='GET', params={}, headers=None, body=None):
        partialPath = self.implode_params(path, params)
        subAccountId = self.safe_string(params, 'subAccountId')
        params = self.omit(params, 'subAccountId')
        if subAccountId == '0':
            subAccountId = None
        elif subAccountId is None:
            subAccountId = self.safe_string(self.options, 'subAccountId')
        query = self.omit(params, self.extract_params(path))
        if query:
            if method == 'POST' or method == 'PUT' or method == 'DELETE':
                body = self.json(query)
            else:
                partialPath += '?' + self.urlencode(query)
        url = self.urls['api'][api] + '/' + partialPath
        signHeaders = None
        if api == 'private':
            full_path = '/v' + self.version + '/' + partialPath
            self.check_required_credentials()
            timestamp = str(self.milliseconds())
            message = timestamp + method.upper() + full_path
            if body is not None:
                message += body
            if subAccountId:
                message += subAccountId
            payloadBase64 = self.string_to_base64(message)
            signature = self.hmac(
                self.base64_to_binary(payloadBase64),
                self.base64_to_binary(self.string_to_base64(self.secret)),
                'sha512',
                'hex'
            )
            signHeaders = {
                # 'Content-Type': 'application/json',
                'X-VALR-API-KEY': self.apiKey,
                'X-VALR-SIGNATURE': signature,
                'X-VALR-TIMESTAMP': timestamp,
            }
            if subAccountId:
                signHeaders['X-VALR-SUB-ACCOUNT-ID'] = subAccountId
        return {'url': url, 'method': method, 'body': body, 'headers': self.deep_extend(headers, signHeaders)}

    def handle_errors(self, statusCode: int, statusText: str, url: str, method: str, responseHeaders: dict, responseBody: str, response, requestHeaders, requestBody):
        if response is None:
            return None  # fallback to the default error handler
        if statusCode == 200 or statusCode == 202:
            return None
        message = self.safe_string(response, 'message')
        errorCode = self.safe_string(response, 'code')
        if errorCode and message:
            errorMessage = self.id + ' - ' + message
            erroCodeStr = str(errorCode)
            self.throw_exactly_matched_exception(self.exceptions['exact'], erroCodeStr, errorMessage)
            self.throw_broadly_matched_exception(self.exceptions['broad'], message, errorMessage)
        return None
